        var liveMatrix = machine.Devices.All.OfType<C64KeyboardMatrix>().Single();
        var keyboardInput = machine.Devices.All.OfType<IMachineKeyboardInput>().Single();

        // Warm a few frames so we are past reset vectors and at instruction boundaries.
        for (var i = 0; i < 5; i++)
            machine.RunFrame();

        var cpu = machine.Devices.All.OfType<ICpu>().Single();
        var pcBefore = cpu.PC;

        keyboardInput.SetRestoreState(true);
        Assert.True(liveMatrix.IsRestorePressed);

        // Advance enough cycles for the edge latch + instruction boundary NMI service.
        // NMI takes the vector at $FFFA/$FFFB; after service PC lands off the prior stream.
        for (var i = 0; i < 200; i++)
            machine.Step();

        // Either PC changed due to NMI vectoring, or we at least still show the assert
        // while the clock has had a chance to edge-latch (hold then release path).
        Assert.True(
            cpu.PC != pcBefore || liveMatrix.IsRestorePressed,
            "RESTORE press should either vector NMI (PC change) or keep the line asserted.");

        keyboardInput.SetRestoreState(false);
        Assert.False(liveMatrix.IsRestorePressed);
    }"}

